        "explanation": "Модели условных предложений:\n1. **Реальное условие (Настоящее / Будущее):**\n   - **אִם (им) + настоящее/будущее -> будущее/повелительное:**\n   - **אִם יִהְיֶה מֶזֶג אֲוִיר יָפֶה, נֵצֵא לַיָּם (им йиhйé мэ́зег авӣр яфэ́, нэцэ́ ла-ям)** — Если будет хорошая погода, мы пойдем на море.\n   - **אִם תִּצְטָרֵךְ עֶזְרָה, תִּתְקַשֵּׁר אֵלַי (им тицтарéх эзрá, титкашэ́р элáй)** — Если тебе понадобится помощь, позвони мне.\n2. **Нереальное сослагательное условие (Прошедшее время «Если бы...»):**\n   - **אִלּוּ / לוּ (илý / лу) + прошедшее -> הָיָה + форма прошедшего:**\n   - **אִלּוּ יָדַעְתִּי, הָיִיתִי בָּא (илý ядáти, hайӣти ба)** — Если бы я знал, я бы пришел.\n   - **אִלּוּ הָיָה לִי כֶּסֶף, הָיִיתִי קוֹנֶה אֶת הַדִּירָה (илý hайá ли кэ́сеф, hайӣти конé...)** — Если бы у меня были деньги, я бы купил эту квартиру.",
