        "explanation": "Формулы сравнения:\n1. **Сравнительная степень (יותר / פחות):**\n   - **יוֹתֵר + прил. + מִ- / מֵהַ-:**\n     - תֵּל אָבִיב יוֹתֵר יְקָרָה מֵחֵיפָה (Тель-Авив дороже Хайфы).\n     - הַסֵּפֶר הַזֶּה יוֹתֵר מְעַנְיֵן מֵהַסֶּרֶט (Эта книга интереснее фильма).\n   - **פָּחוֹת + прил. + מִ-:**\n     - הַיּוֹם פָּחוֹת חַם מֵאֶתְמוֹל (Сегодня менее жарко, чем вчера).\n2. **Превосходная степень (הכי / ביותר):**\n   - **הֲכִי + прилагательное (разговорный стиль):**\n     - הוּא הֲכִי חָכָם (hу hахӣ хахáм — он самый умный).\n     - הַמִּסְעָדָה הֲכִי טוֹבָה בָּעִיר (hа-мисадá hахӣ товá — лучший ресторан в городе).\n   - **определенное прил. + בְּיוֹתֵר (литературный стиль):**\n     - הַתַּלְמִיד הַמִּצְטַיֵּן בְּיוֹתֵר (hа-талмӣд hа-мицтайэ́н бэйотэ́р — самый выдающийся ученик).",
