        "explanation": "Модели по биньянам:\n1. **פָּעַל (Пааль):** модель **פְּעִילָה (пъилá)** (ж.р.):\n   - כָּתַב -> **כְּתִיבָה (ктивá — письмо/написание)**.\n   - לָמַד -> **לְמִידָה (лмидá — учеба/обучение)**.\n   - סָגַר -> **סְגִירָה (сгирá — закрытие)**.\n   - פָּתַח -> **פְּתִיחָה (птихá — открытие)**.\n2. **פִּעֵל (Пиэль):** модель **תַּפְעִיל (тафъӣль)** или **פִּעוּל (пиýль)** (м.р.):\n   - שִׁלֵּם -> **תַּשְׁלוּם (ташлýм — платеж)**.\n   - תִּקֵּן -> **תִּקּוּן (тикýн — ремонт/исправление)**.\n   - סִדֵּר -> **סִדּוּר (сидýр — устройство/молитвенник)**.\n   - בִּקֵּר -> **בִּקּוּר (бикýр — визит/посещение)**.\n3. **הִפְעִיל (hифиль):** модель **הַפְעָלָה (hафъалá)** (ж.р.):\n   - הִזְמִין -> **הַזְמָנָה (hазмана — заказ/приглашение)**.\n   - הִתְחִיל -> **הַתְחָלָה (hатхала — начало)**.\n   - הִרְגִּישׁ -> **הַרְגָּשָׁה (hаргаша — самочувствие)**.\n   - הִסְבִּיר -> **הַסְבָּרָה (hасбара — объяснение/разъяснительная работа)**.\n4. **הִתְפַּעֵל (hитпаэль):** модель **הִתְפַּעֲלוּת (hитпаалýт)** (ж.р.):\n   - הִתְרַגֵּשׁ -> **הִתְרַגְּשׁוּת (hитрагшýт — волнение)**.\n   - הִתְנַהֵג -> **הִתְנַהֲגוּת (hитнаhагýт — поведение)**.\n   - הִתְפַּתֵּחַ -> **הִתְפַּתְּחוּת (hитпатхýт — развитие)**.",
